-- Function: public.fn_record_teacher_attendance
-- Backup generated on 2026-10-25 20:33:46

CREATE OR REPLACE FUNCTION public.fn_record_teacher_attendance(p_id uuid, p_tenant_id uuid, p_branch_id uuid, p_teacher_id uuid, p_attendance_date date, p_status character varying, p_clock_in_time time without time zone, p_clock_out_time time without time zone, p_notes text, p_recorded_by_user_id uuid)  RETURNS TABLE(id uuid, tenant_id uuid, branch_id uuid, teacher_id uuid, attendance_date date, status character varying, clock_in_time time without time zone, clock_out_time time without time zone, notes text, recorded_by_user_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE plpgsql AS $function$ DECLARE     v_actual_teacher_id UUID;     v_attendance_id UUID;     v_user RECORD; BEGIN     SELECT t.id INTO v_actual_teacher_id FROM teachers t WHERE t.id = p_teacher_id OR t.user_id = p_teacher_id LIMIT 1;          IF v_actual_teacher_id IS NULL THEN         SELECT u.id, u.tenant_id, u.first_name, u.last_name, u.display_name INTO v_user FROM users u WHERE u.id = p_teacher_id;         IF v_user.id IS NOT NULL THEN             v_actual_teacher_id := gen_random_uuid();             INSERT INTO teachers (id, tenant_id, user_id, first_name, last_name, display_name, status, created_at, updated_at)             VALUES (                 v_actual_teacher_id,                 COALESCE(NULLIF(p_tenant_id, '00000000-0000-0000-0000-000000000000'::uuid), v_user.tenant_id),                 v_user.id,                 COALESCE(v_user.first_name, 'Teacher'),                 COALESCE(v_user.last_name, ''),                 COALESCE(v_user.display_name, v_user.first_name || ' ' || v_user.last_name),                 'Active', NOW(), NOW()             ) ON CONFLICT (id) DO NOTHING;         ELSE             v_actual_teacher_id := p_teacher_id;         END IF;     END IF;      v_attendance_id := p_id;     IF v_attendance_id IS NULL OR v_attendance_id = '00000000-0000-0000-0000-000000000000'::uuid THEN         SELECT ta.id INTO v_attendance_id         FROM teacher_attendance ta         WHERE ta.branch_id = p_branch_id AND ta.teacher_id = v_actual_teacher_id AND ta.attendance_date = p_attendance_date;                  IF v_attendance_id IS NULL THEN             v_attendance_id := gen_random_uuid();         END IF;     END IF;      INSERT INTO teacher_attendance (         id, tenant_id, branch_id, teacher_id, attendance_date, status, clock_in_time, clock_out_time, notes, recorded_by_user_id, created_at, updated_at     )     VALUES (         v_attendance_id, p_tenant_id, p_branch_id, v_actual_teacher_id, p_attendance_date, p_status, p_clock_in_time, p_clock_out_time, p_notes, p_recorded_by_user_id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP     )     ON CONFLICT (id) DO UPDATE SET          status = EXCLUDED.status, clock_in_time = EXCLUDED.clock_in_time, clock_out_time = EXCLUDED.clock_out_time, notes = EXCLUDED.notes, updated_at = CURRENT_TIMESTAMP;      RETURN QUERY     SELECT ta.id, ta.tenant_id, ta.branch_id, ta.teacher_id, ta.attendance_date, ta.status,            ta.clock_in_time, ta.clock_out_time, ta.notes, ta.recorded_by_user_id, ta.created_at, ta.updated_at     FROM teacher_attendance ta     WHERE ta.id = v_attendance_id; END; $function$ ;
